update public.questions set body_hi = 'पेरिस समझौते के अनुच्छेद 6 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। अनुच्छेद 6.2 पक्षकारों को द्विपक्षीय सहयोग करने और ITMO को अपने NDC में गिनने देता है; अनुच्छेद 6.4 संयुक्त राष्ट्र द्वारा संचालित एक क्रेडिट तंत्र (पेरिस समझौता क्रेडिटिंग तंत्र) बनाता है, जिसे अनुच्छेद 6.4 पर्यवेक्षी निकाय चलाता है और जिसमें CDM गतिविधियाँ स्थानांतरित हो सकती हैं। संगत समायोजन (corresponding adjustments) एक ही कटौती को दो बार गिने जाने से रोकते हैं। फ़रवरी 2023 में भारत ने तीन श्रेणियों (GHG शमन, वैकल्पिक सामग्री और निष्कासन) में 13 गतिविधियाँ तय कीं जिन्हें वह अनुच्छेद 6.2 के व्यापार के लिए विचार करेगा, जैसे हरित हाइड्रोजन, अपतटीय पवन और ज्वारीय ऊर्जा।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अनुच्छेद 6.2 के तहत देश द्विपक्षीय या सहयोगी तरीकों से आपस में अंतरराष्ट्रीय स्तर पर हस्तांतरित शमन परिणामों (ITMO) का हस्तांतरण कर सकते हैं।", "अनुच्छेद 6.4 के तंत्र की निगरानी एक पर्यवेक्षी निकाय करता है, और क्योटो प्रोटोकॉल के स्वच्छ विकास तंत्र (CDM) के तहत पंजीकृत गतिविधियाँ इसमें स्थानांतरित हो सकती हैं।", "संगत समायोजन इसलिए किए जाते हैं ताकि हस्तांतरित उत्सर्जन-कटौती हस्तांतरण करने वाले और प्राप्त करने वाले, दोनों देशों के NDC में न गिनी जाए।", "भारत ने उन गतिविधियों की सूची अंतिम कर ली है जिन पर वह अनुच्छेद 6.2 के तहत कार्बन क्रेडिट के व्यापार के लिए विचार करेगा।"]}'::jsonb where id = '80332089-2dbb-4e79-b3b0-cce2de2ca8cc' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'भारत ने 2070 तक शुद्ध-शून्य (net-zero) उत्सर्जन सहित अपनी ''पंचामृत'' जलवायु प्रतिबद्धताओं की घोषणा कहाँ की?', explanation_hi = 'प्रधानमंत्री ने नवंबर 2021 में ग्लासगो में COP26 में पंचामृत की घोषणा की: 2030 तक 500 GW गैर-जीवाश्म क्षमता, ऊर्जा ज़रूरतों का 50 प्रतिशत नवीकरणीय स्रोतों से, अनुमानित उत्सर्जन में एक अरब टन की कटौती और उत्सर्जन तीव्रता में 45 प्रतिशत कमी, तथा 2070 तक शुद्ध-शून्य।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "COP21, पेरिस", "b": "COP24, कातोवित्से", "c": "COP27, शर्म अल-शेख", "d": "COP26, ग्लासगो"}'::jsonb as hi) h) where id = 'fccdaa49-8114-453b-9bff-c0a6f074086a' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जलवायु परिवर्तन पर संयुक्त राष्ट्र फ्रेमवर्क कन्वेंशन (UNFCCC) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 2 और 3 सही हैं। UNFCCC 1992 में अपनाया गया, रियो में हस्ताक्षर के लिए खोला गया और 1994 में लागू हुआ; इसका अनुच्छेद 3 साझा किंतु विभेदित उत्तरदायित्व का सिद्धांत रखता है। कथन 1 गलत है: कन्वेंशन स्वयं विकसित देशों के लिए केवल एक गैर-बाध्यकारी लक्ष्य रखता है; देश-वार बाध्यकारी लक्ष्य क्योटो प्रोटोकॉल (1997) से आए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह हर विकसित देश के लिए कानूनी रूप से बाध्यकारी उत्सर्जन-कटौती लक्ष्य निर्धारित करता है।", "इसे 1992 में रियो डी जनेरियो के पृथ्वी सम्मेलन में हस्ताक्षर के लिए खोला गया।", "''साझा किंतु विभेदित उत्तरदायित्व और संबंधित क्षमताएँ'' का सिद्धांत इसमें लिखा गया है।"]}'::jsonb where id = '26c6958e-db14-4c87-87b5-4c4f02552cbc' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'UNFCCC के तहत हानि और क्षति (loss and damage) से निपटने के कोष के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2, 3 और 4 सही हैं। COP27 में कोष बनाने पर सहमति हुई, और COP28 ने इसे चालू करने का निर्णय अपनाया, जिसमें विश्व बैंक अंतरिम मेज़बान और न्यासी है। कथन 1 गलत है: विकसित देशों से योगदान में अगुवाई करने का ''आग्रह'' किया गया है और दूसरों को प्रोत्साहित किया गया है, पर योगदान स्वैच्छिक हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसमें योगदान सभी विकसित देशों के लिए कानूनी रूप से अनिवार्य है।", "इसे बनाने पर सहमति 2022 में शर्म अल-शेख में COP27 में हुई।", "इसे 2023 में दुबई में COP28 में चालू किया गया।", "विश्व बैंक एक अंतरिम अवधि के लिए इसकी मेज़बानी एक वित्तीय मध्यस्थ कोष (financial intermediary fund) के रूप में करता है।"]}'::jsonb where id = '025bdaa7-ece0-4e7c-a321-d22f7c290be9' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = '2023 में अधिसूचित भारत का ''हरित क्रेडिट कार्यक्रम'' (Green Credit Programme) निम्नलिखित में से किस कानून के तहत लागू किया जाता है?', explanation_hi = 'हरित क्रेडिट नियम, 2023 अक्टूबर 2023 में पर्यावरण (संरक्षण) अधिनियम, 1986 के तहत अधिसूचित हुए, ताकि वृक्षारोपण और जल संरक्षण जैसे स्वैच्छिक कार्यों को व्यापार-योग्य हरित क्रेडिट से पुरस्कृत किया जा सके; भारतीय वानिकी अनुसंधान और शिक्षा परिषद (ICFRE) इसका प्रशासन करती है। इसके विपरीत, कार्बन बाज़ार ऊर्जा संरक्षण अधिनियम के तहत चलता है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "पर्यावरण (संरक्षण) अधिनियम, 1986", "b": "ऊर्जा संरक्षण अधिनियम, 2001", "c": "वन (संरक्षण) अधिनियम, 1980", "d": "जैव विविधता अधिनियम, 2002"}'::jsonb as hi) h) where id = '5230e30b-4c2e-4804-b70d-d510419fe8e8' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-II और कथन-III दोनों सही हैं, किंतु केवल कथन-II, कथन-I की व्याख्या करता है। समझौते की ''नीचे से ऊपर'' (bottom-up) बनावट हर देश को अपना योगदान स्वयं तय करने देती है, इसीलिए इसके लक्ष्य ''राष्ट्रीय स्तर पर निर्धारित'' हैं। कथन-III भी सही है (अनुच्छेद 4.3 और 4.9: हर पाँच वर्ष पर नया NDC, हर बार पहले से आगे), पर यह NDC के समय और क्रमिक बढ़ोतरी की बात करता है, यह नहीं कि उनका स्तर राष्ट्रीय स्तर पर क्यों तय होता है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "पेरिस समझौते के तहत हर देश स्वयं तय करता है कि वह अपना उत्सर्जन कितना घटाएगा।", "reason_hi": "राष्ट्रीय स्तर पर निर्धारित योगदान (NDC) हर पक्षकार स्वयं तैयार करता है; ये अंतरराष्ट्रीय स्तर पर सौंपे या तय नहीं किए जाते।", "reason_2_hi": "पेरिस समझौता हर पक्षकार से हर पाँच वर्ष पर एक NDC भेजने की अपेक्षा करता है, जिसमें हर बार उसकी सर्वोच्च संभव महत्वाकांक्षा झलके।"}'::jsonb where id = '3b3d2924-b1ab-4039-91c7-a342270253d4' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'UNFCCC के पक्षकारों के सम्मेलनों (COP) और उनके परिणामों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'चारों युग्म सही हैं। COP3 (1997) ने क्योटो प्रोटोकॉल अपनाया; COP13 (2007) ने बाली कार्ययोजना, जिससे दीर्घकालिक सहयोग पर वार्ता शुरू हुई; COP21 (2015) ने पेरिस समझौता; और COP26 (2021) ने ग्लासगो जलवायु संधि, जिसमें बिना नियंत्रण वाली कोयला बिजली को ''धीरे-धीरे घटाने'' (phase down) का आह्वान था।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. COP3, क्योटो", "2. COP13, बाली", "3. COP21, पेरिस", "4. COP26, ग्लासगो"], "list_2_hi": ["क्योटो प्रोटोकॉल", "बाली कार्ययोजना", "पेरिस समझौता", "ग्लासगो जलवायु संधि"]}'::jsonb where id = '5e6e5780-3178-41fd-b2db-7d977774514d' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'पेरिस समझौते के तहत वैश्विक समीक्षा (Global Stocktake) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 2 और 3 सही हैं। अनुच्छेद 14 हर पाँच वर्ष पर समीक्षा का प्रावधान करता है; पहली समीक्षा COP28 में पूरी हुई, जिसके निर्णय में ''ऊर्जा प्रणालियों में जीवाश्म ईंधन से दूर जाने'' और 2030 तक नवीकरणीय क्षमता तीन गुना करने का आह्वान था। कथन 1 गलत है: समीक्षा समझौते के लक्ष्यों की ओर सामूहिक प्रगति का आकलन करती है और दंडात्मक नहीं है; इसके निष्कर्ष देशों के अगले NDC को दिशा देने के लिए हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह हर देश के अनुपालन का अलग-अलग आकलन करती है और पीछे रहने वाले देशों पर दंड लगाती है।", "यह हर पाँच वर्ष पर होती है।", "पहली वैश्विक समीक्षा 2023 में दुबई में COP28 में पूरी हुई।"]}'::jsonb where id = '21d05124-8914-4627-83e3-bd832869c678' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'जलवायु वित्त पर नए सामूहिक परिमाणित लक्ष्य (NCQG) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। COP29 के NCQG ने विकसित देशों की अगुवाई में 2035 तक कम से कम 300 अरब डॉलर प्रति वर्ष का मूल लक्ष्य रखा, जो सभी स्रोतों से 1.3 ट्रिलियन डॉलर प्रति वर्ष के व्यापक आह्वान के भीतर है। इसने कोपेनहेगन में घोषित और 2010 में कानकुन में औपचारिक बनाए गए 100 अरब डॉलर के लक्ष्य की जगह ली। भारत ने इसे बहुत कम बताकर इसके अपनाए जाने पर आपत्ति की।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसे 2024 में बाकू में COP29 में अपनाया गया।", "इसके तहत विकसित देशों को 2035 तक विकासशील देशों के लिए प्रति वर्ष कम से कम 300 अरब अमेरिकी डॉलर जुटाने में अगुवाई करनी है।", "यह सभी पक्षों से 2035 तक विकासशील देशों के लिए वित्त को बढ़ाकर कम से कम 1.3 ट्रिलियन अमेरिकी डॉलर प्रति वर्ष करने का आह्वान करता है।", "यह प्रति वर्ष 100 अरब अमेरिकी डॉलर के उस लक्ष्य की जगह लेता है जिसका वादा विकसित देशों ने पहली बार 2009 में कोपेनहेगन में COP15 में किया था।"]}'::jsonb where id = 'd5f68958-3134-4157-99bb-bb2982e98745' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं। हर वर्ष होने वाला COP कन्वेंशन का सर्वोच्च निकाय है। COP30 नवंबर 2025 में ब्राज़ील के अमेज़न क्षेत्र के बेलेम में हुआ; इससे पहले COP29 बाकू (2024) और COP28 दुबई (2023) में हुए थे।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पक्षकारों का सम्मेलन (COP) UNFCCC का सर्वोच्च निर्णय लेने वाला निकाय है।", "COP30 2025 में ब्राज़ील के बेलेम में हुआ।"]}'::jsonb where id = '983d2901-862a-45c0-891c-979a361eb4ec' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'अंतरराष्ट्रीय सौर गठबंधन (ISA) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन I और III सही हैं। ISA की शुरुआत COP21 में हुई और इसका मुख्यालय गुरुग्राम में है। कथन II गलत है: शुरुआत में इसका ध्यान कर्क और मकर रेखाओं के बीच के सौर-समृद्ध देशों पर था, पर इसके फ्रेमवर्क समझौते में संशोधन ने संयुक्त राष्ट्र के सभी सदस्य देशों के लिए सदस्यता खोल दी।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसकी शुरुआत भारत और फ़्रांस ने 2015 में पेरिस में COP21 में की।", "इसकी सदस्यता केवल उन देशों तक सीमित है जो पूरी तरह कर्क रेखा और मकर रेखा के बीच स्थित हैं।", "इसका मुख्यालय भारत के गुरुग्राम में है।"]}'::jsonb where id = '97bec27b-4f21-4d38-bc4b-fb2eba10ed14' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत की कार्बन क्रेडिट व्यापार योजना, 2023 के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2, 3 और 4 सही हैं। विद्युत मंत्रालय ने जून 2023 में ऊर्जा संरक्षण अधिनियम (2022 में संशोधित) के तहत यह योजना अधिसूचित की, और ऊर्जा दक्षता ब्यूरो इसका प्रशासक है। अपने उत्सर्जन-तीव्रता लक्ष्यों से बेहतर प्रदर्शन करने वाली बाध्य इकाइयों को कार्बन क्रेडिट प्रमाणपत्र मिलते हैं, जिन्हें दूसरे खरीद सकते हैं। कथन 1 गलत है: यह भारत का घरेलू कार्बन बाज़ार है, जिसमें एक अनुपालन तंत्र और एक अलग ऑफ़सेट (स्वैच्छिक) तंत्र है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह UNFCCC सचिवालय द्वारा चलाया जाने वाला एक स्वैच्छिक अंतरराष्ट्रीय बाज़ार है।", "इसे ऊर्जा संरक्षण अधिनियम, 2001 के तहत अधिसूचित किया गया।", "ऊर्जा दक्षता ब्यूरो इसका प्रशासक है।", "इसके अनुपालन तंत्र के तहत ऊर्जा-गहन क्षेत्रों की बाध्य इकाइयों को ग्रीनहाउस गैस उत्सर्जन-तीव्रता के लक्ष्य दिए जाते हैं।"]}'::jsonb where id = '4a34827b-86ff-4d10-9b25-92a4db2d9828' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'वैश्विक तापन क्षमता (GWP) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। GWP किसी गैस द्वारा एक निश्चित अवधि में होने वाले तापन की तुलना उतनी ही मात्रा की CO2 (GWP = 1) से करता है। IPCC AR6 में 100 वर्ष की अवधि में नाइट्रस ऑक्साइड का GWP 273 है, जबकि मीथेन का लगभग 27-30। कथन 2 दोनों बातों में गलत है: मीथेन वायुमंडल में केवल लगभग 12 वर्ष रहती है, इसलिए इसका प्रभाव शुरुआत में केंद्रित होता है; इसका 20 वर्ष का GWP (लगभग 81) 100 वर्ष के GWP से कहीं अधिक है, इसीलिए मीथेन घटाना निकट भविष्य के तापन को रोकने का सबसे तेज़ उपाय माना जाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["100 वर्ष की अवधि में नाइट्रस ऑक्साइड की वैश्विक तापन क्षमता मीथेन से अधिक है।", "20 वर्ष की अवधि में मीथेन की वैश्विक तापन क्षमता 100 वर्ष की अवधि से कम होती है, क्योंकि मीथेन वायुमंडल में कई शताब्दियों तक रहती है।"]}'::jsonb where id = '125ffeae-e9ef-40b3-8aa8-b74cdb012aea' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'जलवायु विज्ञान में ''कार्बन बजट'' शब्द से क्या अभिप्राय है?', explanation_hi = 'चूँकि तापन लगभग संचयी CO2 उत्सर्जन के अनुपात में बढ़ता है, इसलिए तापमान की किसी सीमा का अर्थ है कि शेष ''कार्बन बजट'' सीमित है। AR6 के अनुसार 1.5 डिग्री सेल्सियस के भीतर रहने की 50 प्रतिशत संभावना के लिए 2020 से शेष बजट लगभग 500 अरब टन CO2 था।', updated_at = now() where id = 'a4daa638-19d0-40c9-a038-371e37cdfec6' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'नगरीय ऊष्मा द्वीप (urban heat island) प्रभाव के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। कंक्रीट और डामर दिन में गर्मी सोखते हैं और रात में छोड़ते हैं, कम पेड़ों का अर्थ है वाष्पन से कम ठंडक, और वाहनों तथा एयर कंडीशनरों की अपशिष्ट गर्मी इसे और बढ़ाती है। छतों और फ़ुटपाथों की परावर्तकता (albedo) बढ़ाना और हरियाली बढ़ाना इसके मानक उपाय हैं, जो नगरों की हीट एक्शन योजनाओं का भाग हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नगर प्रायः अपने आसपास के ग्रामीण क्षेत्रों से अधिक गर्म होते हैं, और यह अंतर आम तौर पर रात में सबसे अधिक होता है।", "वनस्पति की जगह कंक्रीट और डामर का आना इसमें योगदान देता है।", "अधिक सूर्य-प्रकाश परावर्तित करने वाली परत से ढकी ''कूल रूफ़'' इसे कम कर सकती हैं।"]}'::jsonb where id = 'c4525400-1b50-452f-b436-c48d07752c22' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'एरोसोल और जलवायु के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1, 2 और 3 सही हैं। सल्फ़ेट कण सूर्य-प्रकाश को बिखेरते हैं और बादलों को चमकीला बनाते हैं, जिससे ग्रीनहाउस तापन का कुछ भाग ढक जाता है; काला कार्बन (कालिख) सूर्य-प्रकाश सोखता है, और बर्फ़ पर जमने पर उसे गहरा करके पिघलना तेज़ करता है। कथन 4 गलत है: निचले वायुमंडल के एरोसोल कुछ दिनों से कुछ हफ़्तों में धुल जाते हैं, इसीलिए इन्हें घटाने से इनका जलवायु प्रभाव जल्दी बदलता है, लंबे समय तक रहने वाली CO2 के विपरीत।', updated_at = now(), question_data = question_data || '{"statements_hi": ["सल्फ़ेट एरोसोल का कुल प्रभाव ठंडक का होता है, क्योंकि वे सूर्य-प्रकाश को वापस अंतरिक्ष में परावर्तित करते हैं।", "काला कार्बन सूर्य-प्रकाश सोखता है और वायुमंडल को गर्म करता है।", "बर्फ़ और हिमनदों पर जमा काला कार्बन उनके पिघलने को तेज़ करता है।", "एरोसोल कार्बन डाइऑक्साइड की तरह वायुमंडल में शताब्दियों तक रहते हैं।"]}'::jsonb where id = '334ed367-b114-44a8-88f3-75346531f8cf' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'स्थायी तुषार-भूमि (पर्माफ़्रॉस्ट) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। पर्माफ़्रॉस्ट में जमे हुए कार्बनिक कार्बन की विशाल मात्रा बंद है; इसके पिघलने पर सूक्ष्मजीव इसका अपघटन करके CO2 और मीथेन छोड़ते हैं, जो तापन पर एक धनात्मक पुनर्निवेश (positive feedback) है। कथन 3 गलत है: पहाड़ी पर्माफ़्रॉस्ट ऊँची पर्वत-शृंखलाओं में, जिनमें हिमालय और तिब्बती पठार भी हैं, व्यापक रूप से मिलता है, और इसका पिघलना ढलानों को अस्थिर बनाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह वह भूमि है जो कम से कम लगातार दो वर्षों तक 0 डिग्री सेल्सियस या उससे नीचे रहती है।", "इसके पिघलने पर कार्बन डाइऑक्साइड और मीथेन निकल सकती हैं, जो तापन को बढ़ाती हैं।", "यह केवल ध्रुवीय क्षेत्रों में मिलती है, हिमालय जैसे ऊँचे पर्वतों में नहीं।"]}'::jsonb where id = '9d319761-c222-45e6-8523-d4afaa532b99' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'महासागरीय अम्लीकरण के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। घुली हुई CO2 कार्बोनिक अम्ल बनाती है, और पूर्व-औद्योगिक समय से समुद्र-सतह का pH लगभग 0.1 इकाई गिर चुका है। कथन 3 उलटा है: बढ़ी हुई अम्लता उन कार्बोनेट आयनों को घटाती है जिनकी ज़रूरत प्रवाल, मोलस्क और कुछ प्लवकों को होती है, जिससे खोल और कंकाल बनाना कठिन हो जाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["महासागरों ने मानवीय गतिविधियों से उत्सर्जित कार्बन डाइऑक्साइड का लगभग एक-चौथाई भाग सोखा है।", "सोखी गई कार्बन डाइऑक्साइड समुद्री जल का pH घटाती है।", "इससे प्रवालों और मोलस्कों के लिए कैल्शियम कार्बोनेट के खोल और कंकाल बनाना आसान हो जाता है।"]}'::jsonb where id = '70988f51-4cdf-4b3f-b07f-0b46229bc41e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-II और कथन-III दोनों सही हैं, किंतु केवल कथन-II, कथन-I की व्याख्या करता है। हिमनदों के सिकुड़ने का मुख्य कारण तापन है (बर्फ़ पर काला कार्बन और धूल इसे और बढ़ाते हैं)। कथन-III सही है, हिमनद बड़ी नदियों के शुष्क मौसम के प्रवाह को बनाए रखते हैं, पर यह उनके अस्तित्व का परिणाम है, उनके घटने का कारण नहीं।', updated_at = now(), question_data = question_data || '{"assertion_hi": "हाल के दशकों में अधिकांश हिमालयी हिमनद बर्फ़ खो रहे हैं।", "reason_hi": "बढ़ता वायु तापमान बर्फ़ के पिघलने को बढ़ा रहा है।", "reason_2_hi": "हिमालयी हिमनद सिंधु, गंगा और ब्रह्मपुत्र जैसी नदियों को जल देते हैं।"}'::jsonb where id = 'bcf27dea-9f04-40f4-8c71-463d38e279e8' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'IPCC की छठी आकलन रिपोर्ट (AR6) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 और 3 सही हैं। AR6 ने मानव-जनित तापन को ''असंदिग्ध'' (unequivocal) कहा और पाया कि 1.5 डिग्री वाले मार्गों के लिए उत्सर्जन को 2019 के स्तर से 2030 तक लगभग 43 प्रतिशत और 2035 तक 60 प्रतिशत घटाना होगा। कथन 1 गलत है: 2011-2020 में वैश्विक सतह तापमान 1850-1900 से लगभग 1.1 डिग्री सेल्सियस अधिक था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने पाया कि 2011-2020 में वैश्विक सतह तापमान 1850-1900 के स्तर से लगभग 2 डिग्री सेल्सियस अधिक था।", "इसने कहा कि यह असंदिग्ध है कि मानवीय प्रभाव ने वायुमंडल, महासागर और भूमि को गर्म किया है।", "इसने पाया कि तापन को बिना या सीमित अतिक्रमण (overshoot) के 1.5 डिग्री सेल्सियस तक सीमित रखने वाले मार्गों में वैश्विक ग्रीनहाउस गैस उत्सर्जन को 2019 के स्तर से 2030 तक लगभग 43 प्रतिशत घटाना होगा।"]}'::jsonb where id = '782219e2-0a50-49b1-8729-b29ec592f83a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'जलवायु परिवर्तन पर अंतर-सरकारी पैनल (IPCC) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है। IPCC 1988 में WMO और UNEP ने बनाया। कथन 1 गलत है: यह अपना शोध या प्रेक्षण नहीं करता; यह प्रकाशित वैज्ञानिक साहित्य का आकलन करता है, और इसकी आकलन रिपोर्टें स्वैच्छिक वैज्ञानिक लिखते हैं तथा सदस्य सरकारें स्वीकृत करती हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह स्वयं मौलिक जलवायु शोध और निगरानी करता है।", "इसकी स्थापना 1988 में विश्व मौसम विज्ञान संगठन और संयुक्त राष्ट्र पर्यावरण कार्यक्रम ने की।"]}'::jsonb where id = '25da1788-baeb-4427-88a9-721f06774f38' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'ईंधन के रूप में हाइड्रोजन के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1, 3 और 4 सही हैं। रंग बताते हैं कि हाइड्रोजन कैसे बनी: हरित (green) नवीकरणीय बिजली से विद्युत-अपघटन द्वारा, धूसर (grey) प्राकृतिक गैस से (स्टीम मीथेन रिफ़ॉर्मिंग), जिसमें CO2 छोड़ दी जाती है। कथन 2 गलत है: नीली (blue) हाइड्रोजन जीवाश्म ईंधन से बनती है, जिसमें CO2 पकड़कर संचित की जाती है; परमाणु-ऊर्जा से विद्युत-अपघटन वाली हाइड्रोजन को कभी-कभी गुलाबी (pink) कहा जाता है। जनवरी 2023 में स्वीकृत राष्ट्रीय हरित हाइड्रोजन मिशन का लक्ष्य 2030 तक कम से कम 50 लाख टन (5 MMT) प्रति वर्ष है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["हरित हाइड्रोजन नवीकरणीय बिजली से पानी के विद्युत-अपघटन द्वारा बनाई जाती है।", "नीली हाइड्रोजन परमाणु ऊर्जा से चलने वाले विद्युत-अपघटन द्वारा बनाई जाती है।", "धूसर हाइड्रोजन प्राकृतिक गैस से, निकलने वाली कार्बन डाइऑक्साइड को पकड़े बिना, बनाई जाती है।", "भारत के राष्ट्रीय हरित हाइड्रोजन मिशन का लक्ष्य 2030 तक प्रति वर्ष कम से कम 50 लाख टन हरित हाइड्रोजन उत्पादन क्षमता है।"]}'::jsonb where id = '8af4c96b-7e0c-4dc3-a6f4-e7ccfa53a1ea' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I सही है, पर न कथन-II सही है और न कथन-III। समुद्र-स्तर इसलिए बढ़ रहा है कि गर्म होता पानी फैलता है (सिकुड़ता नहीं) और भूमि पर स्थित हिमनद तथा ग्रीनलैंड और अंटार्कटिका की हिम-चादरें पिघलकर समुद्र में जा रही हैं। तैरती समुद्री बर्फ़ पहले से अपने भार के बराबर पानी हटाए रहती है, इसलिए उसके पिघलने से समुद्र-स्तर लगभग नहीं बढ़ता।', updated_at = now(), question_data = question_data || '{"assertion_hi": "वैश्विक औसत समुद्र-स्तर बढ़ रहा है।", "reason_hi": "तैरती समुद्री बर्फ़ का पिघलना वैश्विक समुद्र-स्तर बढ़ने का मुख्य कारण है।", "reason_2_hi": "गर्म होने पर समुद्री जल सिकुड़ता है, जिससे बढ़ोतरी का कुछ भाग संतुलित हो जाता है।"}'::jsonb where id = '50ea19bd-90d5-4b10-af87-44369409a2d0' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। मानवीय उत्सर्जन से होने वाले तापन में सबसे बड़ा हिस्सा कार्बन डाइऑक्साइड का है। कथन 2 गलत है: जलवाष्प सबसे प्रचुर ग्रीनहाउस गैस है; हवा गर्म होने पर इसकी मात्रा बढ़ती है, जिससे दूसरी गैसों से होने वाला तापन और बढ़ता है (यह प्रत्यक्ष मानवीय कारक नहीं, एक पुनर्निवेश है)।', updated_at = now(), question_data = question_data || '{"statements_hi": ["मानव-जनित वैश्विक तापन में सबसे बड़ा एकल योगदान कार्बन डाइऑक्साइड का है।", "जलवाष्प ग्रीनहाउस गैस नहीं है।"]}'::jsonb where id = '64e4942d-5343-4210-8a3c-2457ac729ab9' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'सौर विकिरण संशोधन (solar radiation modification) के प्रस्तावों, जैसे समतापमंडल में एरोसोल छिड़कना, का उद्देश्य है:', explanation_hi = 'सौर विकिरण संशोधन सूर्य-प्रकाश को परावर्तित करके पृथ्वी को ठंडा करने का प्रयास है, जैसे समतापमंडल में सल्फ़ेट बनाने वाली गैसें छोड़ना, जो बड़े ज्वालामुखी विस्फोटों के बाद होने वाली ठंडक की नकल है। यह CO2 नहीं हटाता, इसलिए महासागरीय अम्लीकरण नहीं रोकेगा, और इसमें बड़े जोखिम हैं; पहला विकल्प कार्बन पकड़ने और संचित करने (CCS) का, और दूसरा महासागरीय लौह निषेचन का वर्णन है।', updated_at = now() where id = '5029fc61-903b-469b-af34-9746d4dfeabf' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'आर्कटिक वैश्विक औसत से कहीं अधिक तेज़ी से गर्म हो रहा है। इसका मुख्य कारण निम्नलिखित में से कौन-सा है?', explanation_hi = 'यह ''आर्कटिक प्रवर्धन'' (Arctic amplification) मुख्य रूप से बर्फ़ और हिम की परावर्तकता (albedo) के पुनर्निवेश से होता है: चमकीली बर्फ़ और समुद्री हिम घटने पर नीचे की गहरी सतहें अधिक सूर्य-प्रकाश सोखती हैं, जिससे और बर्फ़ पिघलती है। AR6 ने पाया कि आर्कटिक वैश्विक दर से दोगुने से भी अधिक तेज़ी से गर्म हो रहा है। ओज़ोन क्षरण मुख्य रूप से पराबैंगनी विकिरण को बदलता है और अतिरिक्त तापन का कारण नहीं है।', updated_at = now() where id = '01c1b03b-f1d5-4d02-b5f8-068eedcb8b50' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'पारितंत्रों में ऊर्जा-प्रवाह के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन I और III सही हैं। लिंडेमान के दस प्रतिशत नियम के अनुसार एक पोषी स्तर की ऊर्जा का केवल लगभग दसवाँ भाग अगले स्तर तक पहुँचता है। कथन II उलटा है: जलीय पारितंत्रों में चराई खाद्य शृंखला (grazing food chain) ऊर्जा-प्रवाह का मुख्य मार्ग है, जबकि स्थलीय पारितंत्रों में ऊर्जा का कहीं बड़ा भाग अपरद खाद्य शृंखला (detritus food chain) से होकर जाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["एक पोषी स्तर की लगभग 10 प्रतिशत ऊर्जा अगले स्तर तक पहुँचती है।", "जलीय पारितंत्रों में अपरद खाद्य शृंखला ऊर्जा-प्रवाह का मुख्य मार्ग है।", "स्थलीय पारितंत्रों में चराई खाद्य शृंखला की तुलना में अपरद खाद्य शृंखला से होकर ऊर्जा का कहीं बड़ा भाग बहता है।"]}'::jsonb where id = 'a3068632-eb62-4e94-9bd0-d82e4f2be135' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। गर्मी और नमी अपघटन को तेज़ करती हैं, और मुक्त हुए पोषक तत्व घनी वनस्पति लगभग तुरंत सोख लेती है, इसलिए मिट्टी में बहुत कम जमा होता है; भारी वर्षा बाकी का बड़ा भाग बहा ले जाती है। इसीलिए साफ़ किए गए वर्षा-वन की भूमि कुछ ही मौसमों में उर्वरता खो देती है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "उष्णकटिबंधीय वर्षा-वनों के नीचे की मिट्टी आम तौर पर पोषक तत्वों में कमज़ोर होती है।", "reason_hi": "उष्णकटिबंधीय वर्षा-वनों में अधिकांश पोषक तत्व जीवित वनस्पति में रहते हैं और जल्दी पुनर्चक्रित होते हैं, क्योंकि गर्म, नम परिस्थितियाँ अपघटन को तेज़ करती हैं।"}'::jsonb where id = 'b040fc0b-ebdb-4cdd-babc-9ffeb396d41c' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'पारिस्थितिक अनुक्रमण के प्रकारों और उनके आरंभ-स्थल के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल तीन युग्म सही हैं: 1, 2 और 4। बालुकाक्रमक (psammosere) रेत, जैसे तटीय टीलों, पर शुरू होता है; लवणीय मिट्टी या लवणीय जल में होने वाला अनुक्रमण लवणक्रमक (halosere) है। शैलक्रमक (lithosere, चट्टान पर) शुष्कक्रमक (xerosere) का ही एक प्रकार है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. जलक्रमक (Hydrosere)", "2. शैलक्रमक (Lithosere)", "3. बालुकाक्रमक (Psammosere)", "4. शुष्कक्रमक (Xerosere)"], "list_2_hi": ["जलाशय", "नंगी चट्टान", "लवणीय मिट्टी या लवणीय जल", "शुष्क आवास"]}'::jsonb where id = 'eb3400cc-96d6-44e2-84b9-c2de8531f615' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'गॉस का ''प्रतिस्पर्धी अपवर्जन सिद्धांत'' (competitive exclusion principle) कहता है कि:', explanation_hi = 'गॉस के सिद्धांत के अनुसार एक ही संसाधन के लिए प्रतिस्पर्धा करने वाली दो निकट संबंधी प्रजातियाँ अनिश्चित काल तक साथ नहीं रह सकतीं; कमज़ोर प्रतिस्पर्धी अंततः समाप्त हो जाती है। यह तब लागू होता है जब संसाधन सीमित हों। प्रतिस्पर्धी संसाधन-विभाजन (resource partitioning) से फिर भी साथ रह सकते हैं, जैसे मैकआर्थर के वार्बलर पक्षी, जो एक ही पेड़ के अलग-अलग भागों में भोजन करते हैं। तीसरा विकल्प लिंडेमान का दस प्रतिशत नियम है।', updated_at = now() where id = '3455fdee-f876-4d56-a20e-86a8d7341c7b' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'पारिस्थितिक शब्दों और उनके अर्थों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल दो युग्म सही हैं: 1 और 3। युग्म 2 आवास (habitat) का वर्णन करता है; निकेत (niche) किसी जीव की कार्यात्मक भूमिका है, साथ ही वे सारी परिस्थितियाँ और संसाधन जिनका वह उपयोग करता है। युग्म 4 स्थायी अवस्था (standing state) का वर्णन करता है; खड़ी फ़सल (standing crop) किसी निश्चित समय पर किसी पोषी स्तर पर जीवित पदार्थ की मात्रा है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. पारिस्थितिक संक्रमण क्षेत्र (Ecotone)", "2. पारिस्थितिक निकेत (Niche)", "3. क्रमक (Sere)", "4. खड़ी फ़सल (Standing crop)"], "list_2_hi": ["दो समुदायों के बीच का संक्रमण क्षेत्र", "वह भौतिक स्थान जहाँ कोई जीव रहता है", "अनुक्रमण के दौरान एक-दूसरे की जगह लेने वाले समुदायों का क्रम", "किसी निश्चित समय पर मिट्टी में मौजूद पोषक तत्वों की मात्रा"]}'::jsonb where id = '54f30652-14a4-4c18-8abe-7a9941938d7c' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'पारिस्थितिक पिरामिडों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 और 2 सही हैं। हर हस्तांतरण में ऊर्जा ऊष्मा के रूप में खोती है, इसलिए ऊर्जा का पिरामिड कभी उलटा नहीं हो सकता। समुद्र में किसी भी क्षण पादपप्लवकों की खड़ी फ़सल उन पर निर्भर मछलियों के जैवभार से कम होती है (पादपप्लवक बहुत तेज़ी से बनते-मिटते हैं), इसलिए जैवभार का पिरामिड उलटा होता है। कथन 3 गलत है: एक पेड़ पर बहुत-से कीट पलते हैं, इसलिए वह संख्या का पिरामिड उलटा होता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["ऊर्जा का पिरामिड हमेशा सीधा होता है।", "समुद्र में जैवभार का पिरामिड आम तौर पर उलटा होता है, क्योंकि किसी भी समय मछलियों का जैवभार पादपप्लवकों से कहीं अधिक होता है।", "एक बड़े पेड़ और उस पर पलने वाले कीटों के लिए संख्या का पिरामिड सीधा होता है।"]}'::jsonb where id = 'aa7947bd-2921-419f-842d-6074dca0e3d7' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। संक्रमण क्षेत्र में दोनों पड़ोसी समुदायों की प्रजातियाँ और कुछ अपनी प्रजातियाँ भी मिलती हैं, इसलिए यह प्रायः अधिक समृद्ध होता है; यही कोर प्रभाव (edge effect) है। कथन 3 गलत है: कीस्टोन प्रजाति वह है जिसका समुदाय पर प्रभाव उसकी संख्या की तुलना में असामान्य रूप से बड़ा हो। पाठ्यपुस्तक का उदाहरण समुद्री ऊदबिलाव है, जो समुद्री अर्चिन को खाकर केल्प वनों को चरे जाने से बचाता है; कीस्टोन प्रजातियाँ प्रायः संख्या में बिल्कुल अधिक नहीं होतीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पारिस्थितिक संक्रमण क्षेत्र (ecotone) दो पारितंत्रों के बीच का संक्रमण क्षेत्र है, जैसे वह पट्टी जहाँ वन घास के मैदान से मिलता है।", "संक्रमण क्षेत्र में प्रजातियों की संख्या, और कुछ प्रजातियों का घनत्व, प्रायः आसपास के समुदायों से अधिक होता है; इसे कोर प्रभाव (edge effect) कहते हैं।", "परिभाषा के अनुसार, कीस्टोन प्रजाति अपने समुदाय की सबसे अधिक संख्या वाली प्रजाति होती है।"]}'::jsonb where id = '861c9ff6-b9ef-4012-9831-ec65d4355496' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'पारितंत्रों में उत्पादकता के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 और 3 सही हैं। शुद्ध प्राथमिक उत्पादकता (NPP) = सकल प्राथमिक उत्पादकता (GPP) घटा श्वसन में खर्च ऊर्जा, और NPP ही उपभोक्ताओं को उपलब्ध होती है। जैवमंडल की लगभग 170 अरब टन (शुष्क भार) वार्षिक NPP में से महासागर केवल लगभग 55 अरब टन देते हैं। कथन 2 गलत है: द्वितीयक उत्पादकता उपभोक्ताओं द्वारा नया कार्बनिक पदार्थ बनाने की दर है। कथन 4 गलत है: प्राथमिक उत्पादकता पौधों की प्रजाति के साथ-साथ पर्यावरण, पोषक तत्वों की उपलब्धता और पौधों की प्रकाश-संश्लेषण क्षमता पर भी निर्भर करती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["शुद्ध प्राथमिक उत्पादकता, सकल प्राथमिक उत्पादकता में से उत्पादकों द्वारा श्वसन में खर्च की गई ऊर्जा घटाने पर मिलती है।", "द्वितीयक उत्पादकता वह दर है जिस पर उत्पादक नया कार्बनिक पदार्थ बनाते हैं।", "यद्यपि महासागर पृथ्वी की सतह के लगभग 70 प्रतिशत भाग पर हैं, वे जैवमंडल की वार्षिक शुद्ध प्राथमिक उत्पादकता का केवल लगभग एक-तिहाई भाग देते हैं।", "प्राथमिक उत्पादकता केवल किसी क्षेत्र की पौधों की प्रजातियों पर निर्भर करती है, पोषक तत्वों की उपलब्धता या अन्य पर्यावरणीय कारकों पर नहीं।"]}'::jsonb where id = '932e38f2-81bc-47a0-8b1c-18ead49e6d27' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
